#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

extern int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (size < 10 || size > 9216) {
        fprintf(stderr, "Input size %ld out of range [10, 9216]\n", size);
        fclose(f);
        return 1;
    }
    uint8_t *buf = malloc(size);
    if (!buf) {
        fclose(f);
        return 1;
    }
    if (fread(buf, 1, size, f) != (size_t)size) {
        fprintf(stderr, "fread failed\n");
        free(buf);
        fclose(f);
        return 1;
    }
    fclose(f);
    int ret = LLVMFuzzerTestOneInput(buf, size);
    free(buf);
    return ret;
}
EOF
echo "Created test_main.c"

